mapper.select:
SELECT r.id, r.user_id AS userId, r.village_id AS villageId, r.name, r.business_start_time AS businessStartTime, r.business_end_time AS businessEndTime, r.logo_url AS logoUrl, r.address, r.coordinate_lat AS coordinateLat, r.coordinate_lng AS coordinateLng, r.phone, r.notice, r.license_urls AS licenseUrls, r.status, r.create_time AS createTime, r.update_time AS updateTime, v.village_name AS villageName, u.username AS userName, COALESCE(( SELECT COUNT(*) FROM user_collect uc WHERE uc.target_type = 'restaurant' AND uc.target_id = CAST(r.id AS CHAR) ), 0) AS collectNumber, CASE WHEN #{userId} IS NOT NULL AND EXISTS ( SELECT 1 FROM user_collect uc2 WHERE uc2.user_id = #{userId} AND uc2.target_type = 'restaurant' AND uc2.target_id = CAST(r.id AS CHAR) ) THEN 1 ELSE 0 END AS isCollect FROM restaurant r LEFT JOIN village v ON r.village_id = v.id LEFT JOIN sys_user u ON r.user_id = u.id WHERE 1 = 1
AND r.name LIKE CONCAT('%', #{name}, '%')
AND r.status = #{status}
AND r.village_id = #{villageId}
ORDER BY r.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM restaurant r
WHERE 1 = 1

    AND r.name LIKE CONCAT('%', #{name}, '%')


    AND r.status = #{status}


    AND r.village_id = #{villageId}

SELECT name AS '饭馆名字' FROM restaurant WHERE 1 = 1
AND user_id = #{userId}
ORDER BY create_time DESC

SELECT id, name FROM restaurant WHERE 1 = 1
AND user_id = #{userId}
ORDER BY create_time DESC
